def solve(m):
    n = len(m)
    if n == 0:
        return 1
    # Deep copy
    A = [row[:] for row in m]
    det = 1
    for i in range(n):
        # Find pivot
        pivot = -1
        for r in range(i, n):
            if A[r][i] != 0:
                pivot = r
                break
        if pivot == -1:
            return 0
        if pivot != i:
            A[i], A[pivot] = A[pivot], A[i]
            det = -det
        det *= A[i][i]
        if det == 0:
            return 0
        # Eliminate below
        for r in range(i+1, n):
            factor = A[r][i] / A[i][i]
            for c in range(i, n):
                A[r][c] -= factor * A[i][c]
    return int(round(det))

