def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    # Copy to allow mutations
    m = [row[:] for row in matrix]
    det = 1
    sign = 1
    for col in range(n):
        # Find pivot
        pivot = None
        for r in range(col, n):
            if m[r][col] != 0:
                pivot = r
                break
        if pivot is None:
            return 0
        if pivot != col:
            m[pivot], m[col] = m[col], m[pivot]
            sign = -sign
        pivot_val = m[col][col]
        det *= pivot_val
        # Eliminate below
        for r in range(col + 1, n):
            if m[r][col] != 0:
                factor = m[r][col] / pivot_val
                for c in range(col, n):
                    m[r][c] -= factor * m[col][c]
    # Round to integer to avoid floating point errors
    return sign * round(det)

