{"task_id": "T28", "code": "def solve(words, width):
    if not words:
        return []
    lines = []
    current = []
    cur_len = 0
    for w in words:
        if not current:
            current = [w]
            cur_len = len(w)
        else:
            # need cur_len + 1 + len(w) <= width
            if cur_len + 1 + len(w) <= width:
                current.append(w)
                cur_len += 1 + len(w)
            else:
                lines.append(' '.join(current))
                current = [w]
                cur_len = len(w)
    if current:
        lines.append(' '.join(current))
    return lines
